-- Тема 11: Обгон, встречный разъезд — топик id=11, категория id=10
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(10,11,'На каком расстоянии перед железнодорожным переездом запрещён обгон?',
'["Ближе 100 м перед переездом","Ближе 50 м","Ближе 20 м","Обгон разрешён на любом расстоянии, если переезд открыт"]'::jsonb,0,
'Обгон запрещён на железнодорожных переездах и ближе 100 метров перед ними.',1),
(10,11,'Разрешён ли обгон на мостах, путепроводах и эстакадах?',
'["Запрещён","Разрешён при достаточной видимости","Разрешён только легковым автомобилям","Разрешён вне населённых пунктов"]'::jsonb,0,
'Обгон запрещён на мостах, эстакадах, путепроводах и под ними, а также на пересечениях с ограниченной видимостью.',2),
(10,11,'Что обязан сделать водитель обгоняемого ТС, если водитель, следующий сзади, подал сигнал об обгоне?',
'["Не препятствовать обгону и, по возможности, принять правее","Обязан ускориться, чтобы не быть обогнанным","Обязан немедленно остановиться","Должен подать встречный сигнал"]'::jsonb,0,
'Водитель обгоняемого ТС не должен препятствовать обгону, в том числе увеличивая скорость или иными действиями, а по возможности должен принять правее.',3),
(10,11,'Разрешён ли обгон на регулируемых перекрёстках?',
'["Запрещён","Разрешён при зелёном сигнале светофора","Разрешён, если перекрёсток прямой","Разрешён вне населённых пунктов"]'::jsonb,0,
'Обгон запрещён на регулируемых перекрёстках, а также на нерегулируемых при движении по дороге, не являющейся главной.',4),
(10,11,'Что должен сделать водитель перед началом обгона?',
'["Убедиться, что полоса встречного движения свободна на достаточном расстоянии и обгон не создаст опасности","Достаточно включить сигнал поворота","Обгон можно начинать без проверки, если едущий впереди медленно движется","Убедиться только в отсутствии знаков"]'::jsonb,0,
'Перед началом обгона водитель обязан убедиться, что полоса движения, которую он собирается занять, свободна на достаточном для обгона расстоянии, и что при выполнении манёвра он не создаст опасности и помех другим участникам движения.',5),
(10,11,'Разрешён ли обгон при подъезде к вершине подъёма с ограниченной видимостью?',
'["Запрещён","Разрешён с осторожностью","Разрешён, если нет встречных ТС","Разрешён для мотоциклов"]'::jsonb,0,
'Обгон запрещён на опасных поворотах и на участках с ограниченной видимостью, включая конец подъёма (вершину), где видимость дороги ограничена.',6);

-- Тема 12: Остановка и стоянка — топик id=12, категория id=11
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(11,12,'На каком расстоянии от места остановки маршрутных ТС запрещена стоянка (если нет других ТС)?',
'["Ближе 15 м","Ближе 5 м","Ближе 50 м","Ограничений нет"]'::jsonb,0,
'Остановка и стоянка запрещены ближе 15 метров от мест остановки маршрутных транспортных средств.',1),
(11,12,'Как следует ставить ТС на стоянку на дороге вне населённого пункта в тёмное время суток?',
'["Обозначить стоянку знаком аварийной остановки или включить габаритные огни (аварийную сигнализацию)","Достаточно оставить ближний свет фар","Никаких требований нет","Достаточно включить дальний свет"]'::jsonb,0,
'При вынужденной остановке или стоянке в местах с недостаточной видимостью в тёмное время суток должны быть включены габаритные огни (или стояночные огни), а при отсутствии таковой возможности выставлен знак аварийной остановки.',2),
(11,12,'Разрешена ли стоянка на левой стороне дороги в населённых пунктах с односторонним движением?',
'["Разрешена, если это не запрещено знаками","Запрещена в любом случае","Разрешена только для грузовых ТС","Разрешена только ночью"]'::jsonb,0,
'На дорогах с односторонним движением стоянка разрешена как на правой, так и на левой стороне, если это не запрещено соответствующими знаками.',3),
(11,12,'Что означает совместное применение знака "Стоянка запрещена" с табличкой, указывающей нечётные числа месяца?',
'["Стоянка запрещена только по нечётным числам месяца","Стоянка запрещена всегда","Стоянка разрешена только по нечётным числам","Знак применяется только летом"]'::jsonb,0,
'Табличка с указанием чётности чисел месяца ограничивает действие знака "Стоянка запрещена" только указанными днями (например, только по нечётным числам).',4),
(11,12,'На каком расстоянии от железнодорожного переезда запрещена остановка?',
'["Ближе 50 м от шлагбаума или крайнего рельса","Ближе 5 м","Ближе 15 м","Ограничений нет, если шлагбаум открыт"]'::jsonb,0,
'Остановка и стоянка запрещены на железнодорожных переездах и ближе 50 метров от них.',5),
(11,12,'Разрешено ли открывать дверь ТС во время стоянки, если это может создать помеху другим участникам движения?',
'["Запрещено — открывание двери не должно создавать помех другим участникам движения","Разрешено в любом случае","Разрешено только с правой стороны","Разрешено, если ТС находится на обочине"]'::jsonb,0,
'Водителю запрещается открывать двери ТС, если это создаст помехи другим участникам движения.',6);
